import{z as i,x as s,o as e,c as D,q as r,j as l,D as B,d as A,s as n,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"网络爬虫的合规与工程","description":"","frontmatter":{"title":"网络爬虫的合规与工程","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-crawler-compliance.md","filePath":"quant/alt-crawler-compliance.md","lastUpdated":1791063341000}'),C={name:"quant/alt-crawler-compliance.md"};function d(F,E,p,m,u,h){const t=s("Mermaid");return e(),D("div",null,[E[2]||(E[2]=r('<h1 id="网络爬虫的合规与工程" tabindex="-1">网络爬虫的合规与工程 <a class="header-anchor" href="#网络爬虫的合规与工程" aria-label="Permalink to &quot;网络爬虫的合规与工程&quot;">​</a></h1><div class="epigraph"><p>爬虫的第一约束不是带宽，是许可；技术上可复制的抓取，法律上未必可留存，更未必可交易使用。</p><footer>—— 据 hiQ Labs 与 LinkedIn 诉讼（美国联邦第九巡回法院）的公开报道；GDPR 与个人信息保护法的一般原则整理</footer></div><p><a href="/quant/alt-card-data">上一课</a>把卡流水做成发行人残差，域深化四课到此收拢：文本、图谱、地理、卡，各域都有了带时间戳的面板。本课起转入工程单元，处理各域共同的进料口——自采数据。红线主干课已经画了：<a href="/quant/web-data-compliance">网络数据合规</a>确立「公开可见不等于可采集、可存储、可交易使用」，管道第一道是合规清单。本课把清单落成爬虫的<strong>工程件</strong>：许可注册表、礼貌抓取、原始归档、解析漂移监控与删除管道，让「合法且不断源」成为可持续状态而不是一次性的项目验收。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缺口在「要不要」与「怎么做才持续」之间。目标站的 robots 协议与服务条款各异且会单方面修改；反爬措施升级导致断源，而源切断是模型风险——主干课要求预先写替代，问题是怎么写。HTML 结构漂移让解析静默退化：字段还在，内容早已串列，IC 缓慢死亡而监控无告警。抓下来的原始页不归档，事后无法回答「当时页面上是什么」，回填无从检测，回测与实盘的差异无从归因。这四件事没有一件是「更快地抓」，全是许可与可重放性。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>五件工程件。许可注册表：每个源一行——robots 状态、条款摘录、法务复核日期、允许频率、留存期限，源变更走审批再生效。礼貌与身份：遵守协议的抓取延迟、真实自报的 UA、并发上限、失败指数退避——目的是把<strong>被允许的</strong>抓取做得可预测，不是绕过防护；绕过技术措施的方案不进本课，因为它违规且不可复制。原始归档：原始响应与抓取时刻的哈希一起入库，可按时刻重放，回测能回答「当时看到什么」——与<a href="/quant/point-in-time">点时基本面</a>同一思想落到字节层。解析漂移监控：对解析结果做分布监控，对页面结构做签名，变更即告警；金样页面做回归测试，解析代码升级先过金样。删除管道：保留期到期与主体删除请求触发清理，义务来自合同与个人信息保护法，清理动作留痕可审计。</p><p><span class="marginnote">UA（User-Agent，用户代理）是抓取程序自报家门的字符串：浏览器会自报「我是 Chrome」，爬虫也应当如实自报身份与联系方式。伪装成浏览器也许能过防护，但那已属于规避技术措施——本课的立场是「把被允许的抓取做得可预测」，不是潜入。</span></p>',8)),(e(),l(o,null,{default:B(()=>[n(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E8%AE%B8%E5%8F%AF%E6%B3%A8%E5%86%8C%E8%A1%A8%EF%BC%9Arobots%E3%80%81%E6%9D%A1%E6%AC%BE%E3%80%81%E9%A2%91%E7%8E%87%E3%80%81%E7%95%99%E5%AD%98%E6%9C%9F%22%5D%20--%3E%20G%7B%22%E8%AF%A5%E6%BA%90%E5%BD%93%E5%89%8D%E8%A2%AB%E8%AE%B8%E5%8F%AF%EF%BC%9F%22%7D%0A%20%20G%20--%3E%7C%E5%90%A6%7C%20ALT%5B%22%E5%88%87%E6%8D%A2%E6%9B%BF%E4%BB%A3%E6%BA%90%E9%A2%84%E6%A1%88%22%5D%0A%20%20G%20--%3E%7C%E6%98%AF%7C%20FETCH%5B%22%E7%A4%BC%E8%B2%8C%E6%8A%93%E5%8F%96%EF%BC%9A%E9%99%90%E9%80%9F%E3%80%81%E8%87%AA%E6%8A%A5%E3%80%81%E9%80%80%E9%81%BF%22%5D%0A%20%20FETCH%20--%3E%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E5%BD%92%E6%A1%A3%EF%BC%9A%E5%93%8D%E5%BA%94%E5%8A%A0%E5%93%88%E5%B8%8C%EF%BC%8C%E5%8F%AF%E9%87%8D%E6%94%BE%22%5D%0A%20%20RAW%20--%3E%20PARSE%5B%22%E8%A7%A3%E6%9E%90%EF%BC%9A%E5%B8%A6%E7%BB%93%E6%9E%84%E7%AD%BE%E5%90%8D%22%5D%0A%20%20PARSE%20--%3E%20MON%7B%22%E5%88%86%E5%B8%83%E4%B8%8E%E7%AD%BE%E5%90%8D%E6%BC%82%E7%A7%BB%EF%BC%9F%22%7D%0A%20%20MON%20--%3E%7C%E6%98%AF%7C%20FIX%5B%22%E9%87%91%E6%A0%B7%E5%9B%9E%E5%BD%92%E4%B8%8E%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20MON%20--%3E%7C%E5%90%A6%7C%20FEAT%5B%22%E8%BF%9B%E5%85%A5%E7%89%B9%E5%BE%81%E7%AE%A1%E9%81%93%22%5D%0A%20%20RAW%20--%3E%20DEL%5B%22%E5%88%A0%E9%99%A4%E7%AE%A1%E9%81%93%EF%BC%9A%E4%BF%9D%E7%95%99%E6%9C%9F%E4%B8%8E%E5%88%A0%E9%99%A4%E8%AF%B7%E6%B1%82%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("合规件为什么是工程件而不是备忘录：许可会变，注册表让「哪天、哪个源、凭哪条条款」可审计，纠纷时这是唯一的证据；替代源必须预先写成代码路径并过金样回归，断源日的切换才是配置变更而不是救火；原始归档是回填检测的前提——没有当时快照，就测不出供应商或自己的回填（"),a("a",{href:"/quant/alt-data-backfill-bias"},"回填偏差"),A("的四层前视全部因此漏检）。不这么做的错法：合规靠口头约定，断源靠现场想办法，解析退化靠用户投诉发现——三条都会把工程事故变成模型事故。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"robots 协议是行业惯例，服务条款是合同约束，二者绑定方式不同：前者约束自动访问的礼貌，后者约束使用与留存。hiQ 与 LinkedIn 的多年诉讼围绕「抓取公开资料是否构成计算机欺诈」，往返裁定说明不确定性集中在合同与个人数据层面，而不是技术可行性——这正是注册表把两者分列的原因。")],-1)),E[6]||(E[6]=a("p",null,"解析漂移为什么能静默杀死信号、监控如何拦截——回答「字段还在为什么 IC 还是死了」：",-1)),(e(),l(o,null,{default:B(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20D1%5B%22%E4%B8%8A%E6%B8%B8%E6%94%B9%E7%89%88%EF%BC%9AHTML%20%E7%BB%93%E6%9E%84%E5%8F%98%E5%8C%96%22%5D%20--%3E%20D2%5B%22%E8%A7%A3%E6%9E%90%E5%99%A8%E4%BB%8D%E8%BF%94%E5%9B%9E%E5%AD%97%E6%AE%B5%EF%BC%8C%E5%86%85%E5%AE%B9%E4%B8%B2%E5%88%97%22%5D%0A%20%20D2%20--%3E%20D3%5B%22%E6%97%A0%E6%8A%A5%E9%94%99%E3%80%81%E6%97%A0%E5%91%8A%E8%AD%A6%EF%BC%9A%E9%9D%99%E9%BB%98%E9%80%80%E5%8C%96%22%5D%0A%20%20D3%20--%3E%20D4%5B%22%E7%89%B9%E5%BE%81%E5%88%86%E5%B8%83%E7%BC%93%E6%85%A2%E5%81%8F%E7%A7%BB%EF%BC%8CIC%20%E9%80%90%E6%9C%88%E8%A1%B0%E5%87%8F%22%5D%0A%20%20D4%20--%3E%20S1%7B%22%E7%9B%91%E6%8E%A7%E5%9C%A8%E4%BD%8D%E5%90%97%EF%BC%9F%22%7D%0A%20%20S1%20--%3E%7C%22%E5%88%86%E5%B8%83%E7%9B%91%E6%8E%A7%E4%B8%8E%E7%BB%93%E6%9E%84%E7%AD%BE%E5%90%8D%22%7C%20AL%5B%22%E5%8F%98%E6%9B%B4%E5%8D%B3%E5%91%8A%E8%AD%A6%22%5D%0A%20%20AL%20--%3E%20G%5B%22%E9%87%91%E6%A0%B7%E9%A1%B5%E9%9D%A2%E5%9B%9E%E5%BD%92%EF%BC%9A%E5%AE%9A%E4%BD%8D%E5%9D%8F%E5%9C%A8%E5%93%AA%E4%B8%80%E5%B1%82%22%5D%0A%20%20G%20--%3E%20F%5B%22%E4%BF%AE%E5%A4%8D%E8%A7%A3%E6%9E%90%E5%B9%B6%E9%87%8D%E6%94%BE%E5%BD%92%E6%A1%A3%E5%8E%86%E5%8F%B2%22%5D%0A%20%20S1%20--%3E%7C%22%E6%B2%A1%E6%9C%89%E7%9B%91%E6%8E%A7%22%7C%20DEAD%5B%22%E6%95%B0%E6%9C%88%E5%90%8E%E6%89%8D%E5%8F%91%E7%8E%B0%EF%BC%8C%E6%95%B0%E6%8D%AE%E6%95%B4%E6%AE%B5%E6%8A%A5%E5%BA%9F%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<p><span class="marginnote">指数退避就是「失败后翻倍等待」：第一次失败等 2 秒，再失败等 4 秒、8 秒、16 秒，而不是每 2 秒硬撞一次。硬撞会把对方的偶发故障撞成对你的永久封禁；退避既给对方喘息，也让自己的重试集中在对方恢复之后。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只立流程不立判例：辖区差异大——美国计算机欺诈法律的边界、欧盟数据库特别权利、国内个人信息保护法——具体条文以所在司法管辖为准，不在本课伪造。个人数据一律在聚合层以上停留，这与后文各课一致。质量阈值的定义与门禁是下一课的对象；采购与定价归成本结构课；抓取的频率设计只到「被允许的范围内可预测」为止，不做规避技术。</p><p><span class="marginnote">常见误区：「页面公开可见，抓下来就没事」。公开只解决「看到」，不解决「存储期限」「二次分发」与「个人信息」三件事——同一份公开页面里若含个人信息，删除请求一样适用于你。这也是个人数据一律只在聚合层以上停留的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>许可注册表是爬虫的第一张表：robots、条款、频率、留存期，源变更走审批。</li><li>原始归档带哈希可重放，是回填检测与事后审计的字节层前提。</li><li>解析漂移靠分布监控加结构签名加金样回归拦截，静默退化不是宿命。</li><li>替代源预案预先写成代码路径；源切断是模型风险，不是运维新闻。</li><li>出处：hiQ Labs v. LinkedIn（第九巡回法院）公开报道；GDPR、个人信息保护法的一般原则；本课程网络数据合规与回填偏差各课。</li></ul>',6))])}const b=i(C,[["render",d]]);export{f as __pageData,b as default};
